# Expectations are read from the PLAN, so they cannot drift from it.
var plan = PlanValidator.load_plan_file("res://tests/fixtures/ai_plans/fixture_recon_stomps_rich.json")
var dep = plan["deployment"]
var f = GameState.get_meta("pm2b_latch", {})
var side = f.get("1", {})
var suffix = ""
var reserves = []
for e in side.get("reserves", []):
	reserves.append(str(e.get("unit_id", "")))
var emb = side.get("transport_embarkations", {})
var att = side.get("leader_attachments", {})
var missing = []
for e in dep["reserves"]:
	if not reserves.has(str(e["unit"]) + suffix):
		missing.append("reserve " + str(e["unit"]))
if reserves.size() != dep["reserves"].size():
	missing.append("reserve count %d != %d (the plan owns reserves, so the formula must add none)" % [reserves.size(), dep["reserves"].size()])
for e in dep["embarkations"]:
	var t = str(e["transport"]) + suffix
	if not emb.has(t) or not str(emb[t]).contains(str(e["unit"]) + suffix):
		missing.append("embark " + str(e["unit"]))
for e in dep["attachments"]:
	var c = str(e["character"]) + suffix
	if str(att.get(c, "")) != str(e["bodyguard"]) + suffix:
		missing.append("attach " + str(e["character"]))
print("SCENARIO pm2b P1 reserves=%s embark=%s attach=%s missing=%s" % [str(reserves), JSON.stringify(emb), JSON.stringify(att), str(missing)])
return missing.is_empty()

