var plan = PlanValidator.load_plan_file("res://tests/fixtures/ai_plans/fixture_recon_stomps_rich.json")
var dep = plan["deployment"]
var f = GameState.get_meta("pm2b_latch", {})
var side = f.get("2", {})
var suffix = "_P2"
var reserves = []
for e in side.get("reserves", []):
	reserves.append(str(e.get("unit_id", "")))
var emb = side.get("transport_embarkations", {})
var att = side.get("leader_attachments", {})
