return missing.is_empty()

var per_seat = {1: 0, 2: 0}
for batch in AIPlayer._all_decision_records:
	var seat = int(batch.get("player", 0))
	for rec in batch.get("records", []):
		if str(rec.get("decision_type", "")) != "formations":
			continue
		if str(rec.get("context", {}).get("source", "")).begins_with("plan:"):
			per_seat[seat] = int(per_seat.get(seat, 0)) + 1
print("SCENARIO pm2b plan formations records: seat1=%d seat2=%d" % [per_seat.get(1, 0), per_seat.get(2, 0)])
return mini(int(per_seat.get(1, 0)), int(per_seat.get(2, 0)))
